mapper.select:
SELECT COALESCE(MAX(display_order), 0)
FROM travel_plan_items
WHERE travel_plan_day_id = #{travelPlanDayId}

mapper.insert:
INSERT INTO travel_plan_items (
    travel_plan_day_id, content, tag, display_order, created_by_member_id
) VALUES (
    #{travelPlanDayId}, #{content}, #{tag}, #{displayOrder}, #{createdByMemberId}
)
